starterCode.css:
body { font-family: system-ui, sans-serif; padding: 24px; background: #f8fafc; }
form { display: grid; gap: 14px; max-width: 520px; margin: auto; }
fieldset { display: grid; gap: 8px; border: 1px solid #cbd5e1; border-radius: 8px; padding: 16px; }
input[type='text'] { padding: 8px 10px; }
button { width: fit-content; padding: 8px 12px; }
